import java.io.IOException;
import java.io.InterruptedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Executor;
import java.util.concurrent.LinkedBlockingQueue;

/**
 * Collects four-long rows of an initial run import into recycled chunk buffers, and sorts and spills each full chunk on
 * background threads: one run file per (slice, field order). Rows added since the last {@link #commit()} are
 * provisional: {@link #rollback()} drops them, and only committed rows are ever spilled, so a rolled-back native chunk
 * leaves nothing behind.
 *
 * <p>
 * Not thread-safe: one thread adds, commits, rolls back and completes. The sort tasks only read the chunk they were
 * given and hand the buffer back through a concurrent queue.
 */
final class LmdbRunCollector implements Closeable {

	private final String name;
	private final Path directory;
	private final int[][] fieldOrders;
	private final int slices;
	private final Executor executor;
	private static final int INITIAL_ROWS = 1 << 14;
	static final int MAX_MERGE_FILES = 32;

	private final int chunkRows;
	private final BlockingQueue<long[]> freeBuffers = new LinkedBlockingQueue<>();
	private int allocatedBuffers;
	private final List<CompletableFuture<Void>> pending = new ArrayList<>();
	private final List<List<Path>> runs = new ArrayList<>();
	private final List<Path> files = new ArrayList<>();
	private long[] current;
	private int count;
	private int committed;
	private long committedRows;
	private long spilledRows;
	private int nextRun;
	private boolean completed;
	private LmdbSortedRuns.MemoryRun[] memoryRuns;

	/**
	 * @param chunkRows rows per chunk buffer; at most two full buffers exist, one filling while the other is sorted,
	 *                  and the first starts small so a short import never allocates a full chunk
	 * @param slices    runs per field order and chunk; slices of one chunk sort in parallel
	 */
	LmdbRunCollector(String name, Path directory, int[][] fieldOrders, int chunkRows, int slices, Executor executor) {
		if (chunkRows < 1 || slices < 1 || fieldOrders.length == 0) {
			throw new IllegalArgumentException("Invalid run collector shape");
		}
		this.name = name;
		this.directory = directory;
		this.fieldOrders = fieldOrders;
		this.slices = slices;
		this.executor = executor;
		for (int i = 0; i < fieldOrders.length; i++) {
			runs.add(new ArrayList<>());
		}
		this.chunkRows = chunkRows;
		current = new long[LmdbSortedRuns.ROW_LONGS * Math.min(chunkRows, INITIAL_ROWS)];
		allocatedBuffers = 1;
	}

	void add(long a, long b, long c, long d) throws IOException {
		if (count == current.length / LmdbSortedRuns.ROW_LONGS) {
			makeRoom();
		}
		int base = LmdbSortedRuns.ROW_LONGS * count++;
		current[base] = a;
		current[base + 1] = b;
		current[base + 2] = c;
		current[base + 3] = d;
	}

	/** Every row added so far survives a later {@link #rollback()}. */
	void commit() {
		committedRows += count - committed;
		committed = count;
	}

	/** Drops the rows added since the last {@link #commit()}. */
	void rollback() {
		count = committed;
	}

	long committedRows() {
		return committedRows;
	}

	int provisionalRows() {
		return count - committed;
	}

	/**
	 * Waits for every sort task and returns the runs per field order, in the order of the constructor's
	 * {@code fieldOrders}. The committed remainder is sorted in memory rather than spilled: the merge reads it from the
	 * buffer it already occupies, so an import that never filled a chunk touches no run file at all.
	 */
	List<LmdbSortedRuns.Runs> completeRuns() throws IOException {
		if (count != committed) {
			throw new IllegalStateException(name + " runs still hold " + (count - committed) + " provisional rows");
		}
		if (!completed) {
			if (committed > 0) {
				long[] chunk = current;
				int rows = committed;
				List<CompletableFuture<LmdbSortedRuns.MemoryRun>> sorts = new ArrayList<>(fieldOrders.length);
				for (int[] fields : fieldOrders) {
					sorts.add(CompletableFuture.supplyAsync(() -> LmdbSortedRuns.sortInMemory(chunk, 0, rows, fields),
							executor));
				}
				memoryRuns = new LmdbSortedRuns.MemoryRun[fieldOrders.length];
				for (int order = 0; order < fieldOrders.length; order++) {
					memoryRuns[order] = await(sorts.get(order));
				}
			}
			awaitPending();
			consolidateRuns();
			completed = true;
		}
		List<LmdbSortedRuns.Runs> result = new ArrayList<>(runs.size());
		for (int order = 0; order < runs.size(); order++) {
			result.add(new LmdbSortedRuns.Runs(runs.get(order), memoryRuns == null ? null : memoryRuns[order]));
		}
		return result;
	}

	/**
	 * Keep at most32 file buffers/handles per final merge. Install a whole replacement pass before retiring its
	 * sources; partial outputs remain collector-owned for terminal cleanup. Values deliberately retain duplicates.
	 */
	private void consolidateRuns() throws IOException {
		for (int order = 0; order < runs.size(); order++) {
			while (runs.get(order).size() > MAX_MERGE_FILES) {
				List<Path> previous = runs.get(order);
				List<Path> next = new ArrayList<>();
				for (int from = 0; from < previous.size(); from += MAX_MERGE_FILES) {
					Path output = Files.createTempFile(directory, name + "-merge-", ".run");
					files.add(output);
					LmdbSortedRuns.mergeToFile(previous.subList(from,
							Math.min(previous.size(), from + MAX_MERGE_FILES)), fieldOrders[order], output);
					next.add(output);
				}
				runs.set(order, next);
				for (Path source : previous) {
					Files.deleteIfExists(source);
				}
			}
		}
	}

	private static <T> T await(CompletableFuture<T> task) throws IOException {
		try {
			return task.get();
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new InterruptedIOException("Interrupted while sorting the final initial import chunk");
		} catch (ExecutionException e) {
			throw new IOException("Sorting the final initial import chunk failed", e.getCause());
		}
	}

	long spilledRows() {
		return spilledRows;
	}

	private void makeRoom() throws IOException {
		int capacity = current.length / LmdbSortedRuns.ROW_LONGS;
		if (capacity < chunkRows) {
			long[] grown = new long[LmdbSortedRuns.ROW_LONGS * Math.min(chunkRows, Math.multiplyExact(capacity, 2))];
			System.arraycopy(current, 0, grown, 0, LmdbSortedRuns.ROW_LONGS * count);
			current = grown;
			return;
		}
		if (committed == 0) {
			// One native chunk's provisional rows outgrew the buffer: grow it rather than spill uncommitted rows.
			long[] grown = new long[Math.multiplyExact(current.length, 2)];
			System.arraycopy(current, 0, grown, 0, LmdbSortedRuns.ROW_LONGS * count);
			current = grown;
			return;
		}
		dispatch();
	}

	/** Hands the committed prefix to the sorter and moves the provisional tail into a recycled buffer. */
	private void dispatch() throws IOException {
		long[] chunk = current;
		int spillRows = committed;
		int tail = count - committed;
		long[] next = takeBuffer();
		if (next.length < LmdbSortedRuns.ROW_LONGS * tail) {
			next = new long[Math.max(chunk.length, LmdbSortedRuns.ROW_LONGS * tail)];
		}
		System.arraycopy(chunk, LmdbSortedRuns.ROW_LONGS * committed, next, 0, LmdbSortedRuns.ROW_LONGS * tail);
		current = next;
		count = tail;
		committed = 0;
		spilledRows += spillRows;

		List<CompletableFuture<Void>> tasks = new ArrayList<>();
		int sliceRows = Math.max(1, (spillRows + slices - 1) / slices);
		for (int from = 0; from < spillRows; from += sliceRows) {
			int lo = from;
			int hi = Math.min(spillRows, from + sliceRows);
			for (int order = 0; order < fieldOrders.length; order++) {
				Path file = directory.resolve(name + "-" + order + "-" + nextRun++ + ".run");
				files.add(file);
				runs.get(order).add(file);
				int[] fields = fieldOrders[order];
				tasks.add(CompletableFuture.runAsync(() -> {
					try {
						LmdbSortedRuns.sortAndSpill(chunk, lo, hi, fields, file);
					} catch (IOException e) {
						throw new IllegalStateException(e);
					}
				}, executor));
			}
		}
		CompletableFuture<Void> all = CompletableFuture.allOf(tasks.toArray(CompletableFuture[]::new));
		all.whenComplete((ignored, failure) -> freeBuffers.add(chunk));
		pending.add(all);
		pending.removeIf(task -> task.isDone() && !task.isCompletedExceptionally());
	}

	private long[] takeBuffer() throws IOException {
		long[] free = freeBuffers.poll();
		if (free != null) {
			return free;
		}
		if (allocatedBuffers < 2) {
			allocatedBuffers++;
			return new long[LmdbSortedRuns.ROW_LONGS * chunkRows];
		}
		try {
			return freeBuffers.take();
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new InterruptedIOException("Interrupted while waiting for an initial import sort buffer");
		}
	}

	private void awaitPending() throws IOException {
		for (CompletableFuture<Void> task : pending) {
			try {
				task.get();
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new InterruptedIOException("Interrupted while waiting for initial import sort runs");
			} catch (ExecutionException e) {
				Throwable cause = e.getCause();
				if (cause instanceof IllegalStateException && cause.getCause() instanceof IOException io) {
					throw io;
				}
				throw new IOException("Initial import sort run failed", cause);
			}
		}
		pending.clear();
	}

	/** Waits for running sort tasks, then deletes every run file this collector created. */
	@Override
	public void close() throws IOException {
		IOException failure = null;
		for (CompletableFuture<Void> task : pending) {
			try {
				task.join();
			} catch (RuntimeException ignored) {
				// The task's own failure is irrelevant once its run is discarded.
			}
		}
		pending.clear();
		for (Path file : files) {
			try {
				Files.deleteIfExists(file);
			} catch (IOException e) {
				if (failure == null) {
					failure = e;
				} else {
					failure.addSuppressed(e);
				}
			}
		}
		files.clear();
		current = null;
		memoryRuns = null;
		freeBuffers.clear();
		if (failure != null) {
			throw failure;
		}
	}
}
